INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'conservation', 'n.', '/ˌkɒnsəˈveɪʃn/', '(对环境、文物等的)保护;保持', 'Water conservation has greatly improved the river''s quality.', '水资源保护极大改善了这条河的水质。', 'Environmental Protection', 1, 0, 'senior', 'wordlist', 'elective3', 'U3', 'water conservation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'emission', 'n.', '/iˈmɪʃn/', '排放物;散发物;排放', 'We must cut carbon emissions to slow down climate change.', '我们必须减少碳排放以减缓气候变化。', 'Environmental Protection', 2, 0, 'senior', 'wordlist', 'elective3', 'U3', 'carbon emissions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sustainable', 'adj.', '/səˈsteɪnəbl/', '可持续的;合理利用的', 'Clean energy helps us build a sustainable future.', '清洁能源帮助我们建设一个可持续的未来。', 'Environmental Protection', 3, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a sustainable future', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sustain', 'v.', '/səˈsteɪn/', '维持;遭受;承受住', 'A healthy environment can sustain life for many years.', '健康的环境能维持生命许多年。', 'Environmental Protection', 4, 0, 'senior', 'wordlist', 'elective3', 'U3', 'sustain life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fossil', 'n.', '/ˈfɒsl/', '化石', 'Burning fossil fuels releases harmful gases into the air.', '燃烧化石燃料会向空气中排放有害气体。', 'Environmental Protection', 5, 0, 'senior', 'wordlist', 'elective3', 'U3', 'fossil fuel', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fuel', 'n.', '/ˈfjuːəl/', '燃料', 'Coal and oil are the main fuels that pollute the air.', '煤和石油是污染空气的主要燃料。', 'Environmental Protection', 6, 0, 'senior', 'wordlist', 'elective3', 'U3', 'clean fuel', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'carbon dioxide', 'n.', '/ˌkɑːbən daɪˈɒksaɪd/', '二氧化碳', 'Cars produce a lot of carbon dioxide every day.', '汽车每天排放大量二氧化碳。', 'Environmental Protection', 7, 0, 'senior', 'wordlist', 'elective3', 'U3', 'produce carbon dioxide', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'release', 'v./n.', '/rɪˈliːs/', '排放;释放;发布', 'Factories release waste gases that harm the environment.', '工厂排放有害环境的废气。', 'Environmental Protection', 8, 0, 'senior', 'wordlist', 'elective3', 'U3', 'release gases', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'smog', 'n.', '/smɒɡ/', '烟雾(烟与雾混合的空气污染物)', 'Heavy smog made it hard to see across the city.', '浓重的烟雾让人难以看清整座城市。', 'Environmental Protection', 9, 0, 'senior', 'wordlist', 'elective3', 'U3', 'heavy smog', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'garbage', 'n.', '/ˈɡɑːbɪdʒ/', '垃圾;废物', 'Tourists should never throw garbage into the river.', '游客绝不应往河里扔垃圾。', 'Environmental Protection', 10, 0, 'senior', 'wordlist', 'elective3', 'U3', 'throw garbage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'disposal', 'n.', '/dɪˈspəʊzl/', '去掉;清除;处理', 'New rules were made about garbage disposal in the village.', '村里制定了关于垃圾处理的新规定。', 'Environmental Protection', 11, 0, 'senior', 'wordlist', 'elective3', 'U3', 'garbage disposal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'restore', 'v.', '/rɪˈstɔː(r)/', '恢复;使复原;修复', 'Urgent steps were taken to restore the river''s beauty.', '人们采取紧急措施来修复这条河的美景。', 'Environmental Protection', 12, 0, 'senior', 'wordlist', 'elective3', 'U3', 'restore the river', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'restrict', 'v.', '/rɪˈstrɪkt/', '限制;限定;束缚', 'The government decided to restrict the use of plastic bags.', '政府决定限制塑料袋的使用。', 'Environmental Protection', 13, 0, 'senior', 'wordlist', 'elective3', 'U3', 'restrict pollution', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'restriction', 'n.', '/rɪˈstrɪkʃn/', '限制规定;限制法规;约束', 'Vehicle restriction has helped reduce smog in big cities.', '限行措施帮助减少了大城市的烟雾。', 'Environmental Protection', 14, 0, 'senior', 'wordlist', 'elective3', 'U3', 'vehicle restriction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'harmonious', 'adj.', '/hɑːˈməʊniəs/', '和谐的', 'The villagers now live in a harmonious way with nature.', '村民们如今与自然和谐相处。', 'Environmental Protection', 15, 0, 'senior', 'wordlist', 'elective3', 'U3', 'live in harmony', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'ecology', 'n.', '/iˈkɒlədʒi/', '生态;生态学', 'Planting trees helps protect the local ecology.', '植树有助于保护当地的生态。', 'Environmental Protection', 16, 0, 'senior', 'wordlist', 'elective3', 'U3', 'protect the ecology', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tolerate', 'v.', '/ˈtɒləreɪt/', '忍受;包容;容许', 'The villagers could no longer tolerate the dirty air.', '村民们再也无法忍受污浊的空气。', 'Environmental Protection', 17, 0, 'senior', 'wordlist', 'elective3', 'U3', 'tolerate the smell', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'starve', 'v.', '/stɑːv/', '(使)挨饿;饿死', 'Many polar bears may starve as the ice melts away.', '随着冰雪融化,许多北极熊可能会挨饿。', 'Environmental Protection', 18, 0, 'senior', 'wordlist', 'elective3', 'U3', 'starve to death', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'melt', 'v.', '/melt/', '(使)融化;熔化;软化', 'As the earth gets warmer, the ice begins to melt.', '随着地球变暖,冰雪开始融化。', 'Environmental Protection', 19, 0, 'senior', 'wordlist', 'elective3', 'U3', 'ice melts', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'trend', 'n.', '/trend/', '趋势;趋向;动向', 'Rising temperatures are a worrying trend for our planet.', '气温上升对我们的星球来说是一个令人担忧的趋势。', 'Environmental Protection', 20, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a worrying trend', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'comprehensive', 'adj.', '/ˌkɒmprɪˈhensɪv/', '全部的;所有的;详尽的', 'A comprehensive plan was started to clean up the river.', '人们启动了一项全面的计划来清理河流。', 'Environmental Protection', 21, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a comprehensive plan', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'implement', 'v.', '/ˈɪmplɪment/', '使生效;贯彻;执行', 'The city worked hard to implement the new green policy.', '这座城市努力贯彻新的环保政策。', 'Environmental Protection', 22, 0, 'senior', 'wordlist', 'elective3', 'U3', 'implement a policy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'policy', 'n.', '/ˈpɒləsi/', '政策;方针;原则', 'A good energy policy can reduce carbon emissions.', '好的能源政策能减少碳排放。', 'Environmental Protection', 23, 0, 'senior', 'wordlist', 'elective3', 'U3', 'an energy policy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'regulation', 'n.', '/ˌreɡjuˈleɪʃn/', '章程;规章制度', 'Strict regulations stopped the factories from polluting.', '严格的规章制度阻止了工厂污染。', 'Environmental Protection', 24, 0, 'senior', 'wordlist', 'elective3', 'U3', 'strict regulations', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'reform', 'n./v.', '/rɪˈfɔːm/', '改革;变革;(使)改正', 'An energy reform encouraged people to use clean power.', '一项能源改革鼓励人们使用清洁能源。', 'Environmental Protection', 25, 0, 'senior', 'wordlist', 'elective3', 'U3', 'energy reform', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'enterprise', 'n.', '/ˈentəpraɪz/', '公司;企业;事业', 'Dozens of polluting enterprises were closed or moved.', '数十家污染企业被关闭或迁走。', 'Environmental Protection', 26, 0, 'senior', 'wordlist', 'elective3', 'U3', 'polluting enterprises', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'inspection', 'n.', '/ɪnˈspekʃn/', '检查;查看;视察', 'Officials carry out inspections to find pollution problems.', '官员们进行检查以发现污染问题。', 'Environmental Protection', 27, 0, 'senior', 'wordlist', 'elective3', 'U3', 'carry out inspections', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fine', 'v.', '/faɪn/', '对……处以罚款', 'The local authorities fine companies that pollute the river.', '当地政府对污染河流的公司处以罚款。', 'Environmental Protection', 28, 0, 'senior', 'wordlist', 'elective3', 'U3', 'fine polluters', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'seize', 'v.', '/siːz/', '抓住;夺取;控制', 'We must seize the chance to protect our environment now.', '我们必须抓住机会现在就保护环境。', 'Environmental Protection', 29, 0, 'senior', 'wordlist', 'elective3', 'U3', 'seize the chance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'submit', 'v.', '/səbˈmɪt/', '提交;呈递;屈服', 'Students will submit a report on water pollution next week.', '学生们下周将提交一份关于水污染的报告。', 'Environmental Protection', 30, 0, 'senior', 'wordlist', 'elective3', 'U3', 'submit a report', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sensitive', 'adj.', '/ˈsensətɪv/', '敏感的;善解人意的;灵敏的', 'Nuclear power is a sensitive topic for many people.', '核能对许多人来说是一个敏感话题。', 'Environmental Protection', 31, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a sensitive topic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'moderate', 'adj.', '/ˈmɒdərət/', '适度的;中等的;温和的', 'Moderate use of energy at home saves both money and power.', '家中适度用能既省钱又省电。', 'Environmental Protection', 32, 0, 'senior', 'wordlist', 'elective3', 'U3', 'moderate use', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'footprint', 'n.', '/ˈfʊtprɪnt/', '足迹;(碳)足迹;面积', 'Riding a bike helps to lower your carbon footprint.', '骑自行车有助于降低你的碳足迹。', 'Environmental Protection', 33, 0, 'senior', 'wordlist', 'elective3', 'U3', 'carbon footprint', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'originate', 'v.', '/əˈrɪdʒɪneɪt/', '起源;发源;创立', 'The word ''smog'' originated in Britain long ago.', 'smog 这个词很久以前起源于英国。', 'Environmental Protection', 34, 0, 'senior', 'wordlist', 'elective3', 'U3', 'originate in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'frequently', 'adv.', '/ˈfriːkwəntli/', '频繁地;经常', 'Many visitors frequently threw rubbish into the water.', '许多游客经常往水里扔垃圾。', 'Environmental Protection', 35, 0, 'senior', 'wordlist', 'elective3', 'U3', 'frequently throw', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'nuclear', 'adj.', '/ˈnjuːkliə(r)/', '原子能的;核能的;原子核的', 'Some people worry that nuclear power is not safe.', '有些人担心核能不安全。', 'Environmental Protection', 36, 0, 'senior', 'wordlist', 'elective3', 'U3', 'nuclear power', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'methane', 'n.', '/ˈmiːθeɪn/', '甲烷;沼气', 'Cattle farms release a lot of methane into the air.', '养牛场向空气中排放大量甲烷。', 'Environmental Protection', 37, 0, 'senior', 'wordlist', 'elective3', 'U3', 'methane gas', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tropical', 'adj.', '/ˈtrɒpɪkl/', '热带的;来自热带的', 'Cutting down tropical forests harms the whole planet.', '砍伐热带森林危害整个星球。', 'Environmental Protection', 38, 0, 'senior', 'wordlist', 'elective3', 'U3', 'tropical forest', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'jungle', 'n.', '/ˈdʒʌŋɡl/', '(热带)丛林;密林', 'Many rare animals live deep in the thick jungle.', '许多珍稀动物生活在茂密的丛林深处。', 'Environmental Protection', 39, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a thick jungle', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'basin', 'n.', '/ˈbeɪsn/', '流域;盆地;盆', 'Pollution in the river basin affects millions of people.', '河流流域的污染影响着数百万人。', 'Environmental Protection', 40, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a river basin', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'waterway', 'n.', '/ˈwɔːtəweɪ/', '水道;航道', 'China''s waterways are heading towards a cleaner future.', '中国的水道正迈向更清洁的未来。', 'Environmental Protection', 41, 0, 'senior', 'wordlist', 'elective3', 'U3', 'clean waterways', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'habitable', 'adj.', '/ˈhæbɪtəbl/', '适合居住的', 'We must keep the earth a habitable planet for all life.', '我们必须让地球保持适合一切生命居住。', 'Environmental Protection', 42, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a habitable planet', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'annual', 'adj.', '/ˈænjuəl/', '每年的;一年的', 'The annual report showed that the air quality had improved.', '年度报告显示空气质量已经改善。', 'Environmental Protection', 43, 0, 'senior', 'wordlist', 'elective3', 'U3', 'annual report', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'agenda', 'n.', '/əˈdʒendə/', '议程表;议事日程', 'A clean-up campaign was added to the government agenda.', '一项清理行动被列入了政府的议事日程。', 'Environmental Protection', 44, 0, 'senior', 'wordlist', 'elective3', 'U3', 'on the agenda', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'graph', 'n.', '/ɡrɑːf/', '图;图表;曲线图', 'The graph shows how carbon emissions have risen each year.', '这张图表显示了碳排放如何逐年上升。', 'Environmental Protection', 45, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a line graph', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'worldwide', 'adj./adv.', '/ˌwɜːldˈwaɪd/', '世界各地的;遍及全球地', 'Climate change is a serious worldwide problem today.', '气候变化是当今一个严重的全球性问题。', 'Environmental Protection', 46, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a worldwide problem', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u3.01', '①陈述句的间接引语(say/tell + that;时态后移、人称变换)', 'A2', 12, '选择性必修三 U3 — 直接引语是陈述句时,用 that 引导(可省略),主句一般过去时则从句时态相应后移(do→did, is→was, will→would, have done→had done),人称随说话人/听话人变换。', 1, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u3.02', '②疑问句的间接引语(一般疑问→if/whether;特殊疑问→wh-词;一律陈述语序)', 'A2', 12, '选择性必修三 U3 — 一般疑问句转述用 if/whether 引导;特殊疑问句保留 wh- 疑问词;两者都要变成「陈述语序」(主语在前、动词在后,不再倒装),并完成时态后移与人称变换。', 2, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u3.03', '③祈使句的间接引语(tell/ask/order/advise sb (not) to do)+ 时间/地点状语呼应', 'A2', 12, '选择性必修三 U3 — 祈使句转述用 tell/ask/order/advise + sb + (not) to do;同时时间/地点指示词要呼应:now→then, today→that day, tomorrow→the next day, here→there, this→that。', 3, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'He said, "I recycle paper every week." → He said that he ____ paper every week.', 'recycled', 'recycle', 'recycles', 'will recycle', 'A', '主句 said 过去时,从句一般现在 recycle 后移为一般过去 recycled;人称 I→he。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'She said, "The air is getting cleaner." → She said that the air ____ getting cleaner.', 'is', 'was', 'were', 'be', 'B', '现在进行 is getting 后移为过去进行 was getting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'The expert said, "Polar bears will die out." → The expert said that polar bears ____ die out.', 'will', 'shall', 'would', 'are going to', 'C', 'will 后移为 would。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'Tom said, "I have planted ten trees." → Tom said that he ____ ten trees.', 'has planted', 'planted', 'plants', 'had planted', 'D', '现在完成 have planted 后移为过去完成 had planted。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'She said, "We can save a lot of water." → She said that they ____ save a lot of water.', 'could', 'can', 'may', 'must', 'A', 'can 后移为 could;人称 we→they。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'He told me, "The factory released waste gas." → He told me that the factory ____ released waste gas.', 'has', 'had', 'have', 'will have', 'B', '一般过去 released 后移为过去完成 had released。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'Lily said, "I am cutting my carbon footprint." → Lily said that she ____ cutting her carbon footprint.', 'is', 'are', 'was', 'be', 'C', '现在进行 am cutting 后移为过去进行 was cutting;人称 I→she。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'They said, "The river is badly polluted." → They said that the river ____ badly polluted.', 'is', 'be', 'were', 'was', 'D', 'is 后移为 was;主语 the river 单数。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'He said, "I don''t waste electricity at home." → He said that he ____ waste electricity at home.', 'didn''t', 'doesn''t', 'don''t', 'won''t', 'A', '一般现在否定 don''t 后移为一般过去 didn''t。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'She said, "Smog has become a serious problem." → She said that smog ____ become a serious problem.', 'has', 'had', 'have', 'will have', 'B', '现在完成 has become 后移为过去完成 had become。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'Ben said, "We are going to plant more trees." → Ben said that they ____ going to plant more trees.', 'are', 'is', 'were', 'be', 'C', 'be going to 中的 are 后移为 were;人称 we→they。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'The girl said, "I will turn off the lights." → The girl said that she ____ turn off the lights.', 'will', 'shall', 'is going to', 'would', 'D', 'will 后移为 would;人称 I→she。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'He said, "People throw too much garbage away." → He said that people ____ too much garbage away.', 'threw', 'throw', 'throws', 'have thrown', 'A', '一般现在 throw 后移为一般过去 threw。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'Mum said, "The ice is melting fast." → Mum said that the ice ____ melting fast.', 'is', 'was', 'were', 'be', 'B', 'is melting 后移为 was melting。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'She said, "I have never used a plastic bag." → She said that she ____ never used a plastic bag.', 'has', 'have', 'had', 'did', 'C', '现在完成 have used 后移为过去完成 had used。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'He said, "Clean energy can sustain our future." → He said that clean energy ____ sustain their future.', 'can', 'may', 'should', 'could', 'D', 'can 后移为 could。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'The reporter said, "The smog killed many people." → The reporter said that the smog ____ killed many people.', 'had', 'has', 'have', 'will have', 'A', '一般过去 killed 后移为过去完成 had killed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'Sara said, "I am saving water at home." → Sara said that she ____ saving water at home.', 'is', 'was', 'were', 'are', 'B', 'am saving 后移为 was saving;人称 I→she。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'They said, "We don''t burn coal any more." → They said that they ____ burn coal any more.', 'don''t', 'doesn''t', 'didn''t', 'won''t', 'C', '一般现在否定 don''t 后移为一般过去 didn''t。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.01'), 'He said, "The trees will protect the soil." → He said that the trees ____ protect the soil.', 'will', 'shall', 'are going to', 'would', 'D', 'will 后移为 would。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "Do you save water at home?" → She asked ____ I saved water at home.', 'if', 'that', 'what', 'do', 'A', '一般疑问句转述用 if/whether 引导,并变陈述语序。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "What can we do to help?" → He asked what we ____ do to help.', 'can', 'could', 'may', 'should', 'B', '特殊疑问句保留 what,用陈述语序,can 后移为 could。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'The reporter asked, "Will polar bears die out?" → The reporter asked ____ polar bears would die out.', 'that', 'what', 'whether', 'why', 'C', '一般疑问句用 whether 引导;will 后移为 would。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "Why is smog so harmful?" → She asked why smog ____ so harmful.', 'is', 'be', 'were', 'was', 'D', '保留 why,陈述语序,is 后移为 was。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "How do you cut carbon emissions?" → He asked how I ____ carbon emissions.', 'cut', 'cuts', 'did cut', 'cutting', 'A', '陈述语序去掉助动词 do,cut 后移仍为 cut(原形=过去式)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'They asked, "Are the rivers getting cleaner?" → They asked ____ the rivers were getting cleaner.', 'that', 'whether', 'what', 'how', 'B', '一般疑问句用 whether 引导,变陈述语序。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "Where does the smog come from?" → She asked where the smog ____ from.', 'come', 'comes', 'came', 'coming', 'C', '陈述语序、去 does,comes 后移为 came。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "Can we still save the forest?" → He asked ____ we could still save the forest.', 'that', 'what', 'why', 'if', 'D', '一般疑问句用 if 引导;can 后移为 could。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'The teacher asked, "What causes climate change?" → The teacher asked what ____ climate change.', 'caused', 'cause', 'causes', 'did cause', 'A', 'what 作主语,causes 后移为 caused。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "Have you joined the clean-up?" → She asked ____ I had joined the clean-up.', 'that', 'whether', 'what', 'how', 'B', '一般疑问句用 whether 引导;have joined 后移为 had joined。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "When will the new policy start?" → He asked when the new policy ____ start.', 'will', 'shall', 'would', 'is going to', 'C', '保留 when,陈述语序,will 后移为 would。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'They asked, "Why did the factory close?" → They asked why the factory ____ closed.', 'has', 'have', 'did', 'had', 'D', '保留 why、陈述语序;一般过去 did close 后移为 had closed。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "Do the villagers recycle waste?" → She asked if the villagers ____ waste.', 'recycled', 'recycle', 'recycles', 'recycling', 'A', 'if 引导、陈述语序、去 do;recycle 后移为 recycled。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "How much water do we waste?" → He asked how much water we ____.', 'waste', 'wasted', 'wastes', 'wasting', 'B', '陈述语序去 do;waste 后移为 wasted。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'The expert asked, "Is nuclear power safe?" → The expert asked ____ nuclear power was safe.', 'that', 'what', 'whether', 'why', 'C', '一般疑问句用 whether 引导;is 后移为 was。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "What are you doing for the planet?" → She asked what I ____ doing for the planet.', 'am', 'is', 'were', 'was', 'D', '陈述语序;am doing 后移为 was doing(I→第三人称由说话人决定,这里转述者用 was)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "Can the river be cleaned up?" → He asked ____ the river could be cleaned up.', 'whether', 'that', 'what', 'how', 'A', '一般疑问句用 whether 引导;can 后移为 could。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'They asked, "How has the air improved?" → They asked how the air ____ improved.', 'has', 'had', 'have', 'did', 'B', '保留 how;现在完成 has improved 后移为过去完成 had improved。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'She asked, "Do we need stricter rules?" → She asked if we ____ stricter rules.', 'need', 'needs', 'needed', 'needing', 'C', 'if 引导、陈述语序、去 do;need 后移为 needed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.02'), 'He asked, "Which energy is cleaner?" → He asked which energy ____ cleaner.', 'is', 'be', 'were', 'was', 'D', '保留 which,陈述语序,is 后移为 was。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Turn off the lights, please," she said. → She told us ____ off the lights.', 'to turn', 'turn', 'turning', 'turned', 'A', '祈使句转述用 tell sb to do。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Don''t throw garbage into the river," he said. → He told the tourists ____ throw garbage into the river.', 'to not', 'not to', 'don''t', 'not', 'B', '否定祈使句用 tell sb not to do。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Please save water," the teacher said. → The teacher asked us ____ water.', 'save', 'saving', 'to save', 'saved', 'C', 'ask sb to do 转述请求型祈使句。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Let''s work together to stop pollution," the expert said. → The expert advised us ____ together to stop pollution.', 'work', 'working', 'worked', 'to work', 'D', 'advise sb to do 转述建议型祈使句。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Stop burning coal now," the officer said. → The officer ordered them to stop burning coal ____.', 'then', 'now', 'today', 'here', 'A', '时间状语呼应:now→then。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Plant more trees here," she said. → She told us to plant more trees ____.', 'here', 'there', 'this', 'now', 'B', '地点状语呼应:here→there。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Recycle this bottle," he said. → He told me to recycle ____ bottle.', 'this', 'these', 'that', 'the next', 'C', '指示词呼应:this→that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Submit your report tomorrow," the teacher said. → The teacher told us to submit our report ____.', 'tomorrow', 'today', 'now', 'the next day', 'D', '时间状语呼应:tomorrow→the next day。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Don''t waste electricity," Mum said. → Mum told me ____ electricity.', 'not to waste', 'not waste', 'don''t waste', 'to not waste', 'A', '否定祈使句用 tell sb not to do。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Use cloth bags instead of plastic," she said. → She advised us ____ cloth bags instead of plastic.', 'use', 'to use', 'using', 'used', 'B', 'advise sb to do 转述建议。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Don''t print documents unless necessary," Sally said. → Sally asked us ____ documents unless necessary.', 'to not print', 'don''t print', 'not to print', 'not print', 'C', '否定祈使句用 ask sb not to do。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Take shorter showers today," he said. → He told them to take shorter showers ____.', 'today', 'now', 'here', 'that day', 'D', '时间状语呼应:today→that day。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Walk or ride a bike," Jack said. → Jack advised me ____ or ride a bike.', 'to walk', 'walk', 'walking', 'walked', 'A', 'advise sb to do 转述建议。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Keep this room clean," she said. → She told us to keep ____ room clean.', 'this', 'that', 'these', 'those', 'B', '指示词呼应:this→that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Turn off the heater now," Dad said. → Dad ordered us to turn off the heater ____.', 'now', 'here', 'then', 'today', 'C', '时间状语呼应:now→then。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Don''t drop litter here," the guard said. → The guard told us not to drop litter ____.', 'here', 'this', 'now', 'there', 'D', '地点状语呼应:here→there。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Please share books with others," Joe said. → Joe asked us ____ books with others.', 'to share', 'share', 'sharing', 'shared', 'A', 'ask sb to do 转述请求。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Clean up the beach tomorrow," she said. → She told the volunteers to clean up the beach ____.', 'tomorrow', 'the next day', 'today', 'now', 'B', '时间状语呼应:tomorrow→the next day。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Don''t use the car for short trips," he said. → He advised us ____ the car for short trips.', 'not use', 'to not use', 'not to use', 'don''t use', 'C', '否定祈使句用 advise sb not to do。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U3' AND code='e3u3.03'), '"Plant this tree carefully," the worker said. → The worker told the boy to plant ____ tree carefully.', 'this', 'these', 'those', 'that', 'D', '指示词呼应:this→that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Climate Change and the Polar Bears', 'Far in the north, the polar bears are in trouble. They depend on sea ice to hunt seals, which give them the fat they need to live through the long winter. But as the earth grows warmer, the ice begins to melt earlier each spring and forms later each autumn. With less ice, the bears must swim farther and farther to find food. Some grow weak, and a few even starve before the ice returns. Scientists say this worrying trend is caused by climate change. When we burn fossil fuels such as coal and oil, we release carbon dioxide into the air, and this gas traps heat around the planet. The warming does not only harm the bears; it also raises the level of the sea and changes the weather everywhere. The good news is that it is not too late. If people use clean energy and cut their carbon emissions, the ice may stop disappearing so fast. Saving the bears, in the end, means saving ourselves too.', '说明·气候变化与北极熊', 168, '[{"q":"Why is the sea ice so important to the polar bears?","answer":"A","options":["It allows them to hunt the seals they feed on.","It keeps their fur clean and white.","It is a good place for them to sleep.","It protects them from other bears."],"explanation":"原文 ''depend on sea ice to hunt seals, which give them the fat'' 的转述。"},{"q":"According to the text, what causes the ice to melt?","answer":"B","options":["The bears swimming too much.","Heat trapped by gases from burning fossil fuels.","Too many seals in the water.","A natural change with no cause."],"explanation":"原文 ''burn fossil fuels… release carbon dioxide… traps heat'' 的转述。"},{"q":"What hopeful message does the writer give at the end?","answer":"A","options":["Using clean energy may slow the loss of ice.","The bears can never be saved now.","Only scientists can fix the problem.","The weather will soon become normal by itself."],"explanation":"末段 ''If people use clean energy and cut their carbon emissions, the ice may stop disappearing'' 的转述。"}]'::jsonb, '[{"word":"melt","cn":"融化"},{"word":"starve","cn":"挨饿"},{"word":"emission","cn":"排放(物)"}]'::jsonb, 2, 'elective3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Great Smog of London', 'The word ''smog'' originated in Britain, where it was formed by joining ''smoke'' and ''fog''. In the middle of the last century, many British homes and factories burned huge amounts of coal. The dirty smoke mixed with the wet fog of winter, and thick smog often covered the cities. The worst event happened in London in 1952. For several days a grey cloud hung over the streets, and people could hardly see in front of them. The smog was so harmful that thousands of people became ill, and many of them lost their lives. After this disaster, the government understood that something had to change. New laws restricted the burning of coal in homes and forced factories to clean up the gases they released. Slowly the air grew clearer, and the killer smog never returned in the same way. The story of London is now a warning to other cities: when we pollute the air we breathe, we put our own health and lives in danger.', '记叙·伦敦烟雾事件', 166, '[{"q":"How was the word ''smog'' first made?","answer":"B","options":["By copying a French word.","By joining the words ''smoke'' and ''fog''.","From the name of a city.","From a kind of coal."],"explanation":"原文 ''formed by joining \"smoke\" and \"fog\"'' 的转述。"},{"q":"What made the smog so deadly in 1952?","answer":"C","options":["It blew away too quickly.","It only damaged buildings.","So many people fell ill that many died.","It happened far from any city."],"explanation":"原文 ''thousands of people became ill, and many of them lost their lives'' 的转述。"},{"q":"What did the government do after the disaster?","answer":"D","options":["It did nothing at all.","It banned all factories forever.","It moved everyone out of London.","It limited coal burning and made factories clean their gases."],"explanation":"原文 ''restricted the burning of coal… forced factories to clean up the gases'' 的转述。"}]'::jsonb, '[{"word":"smog","cn":"烟雾"},{"word":"originate","cn":"起源"},{"word":"restrict","cn":"限制"}]'::jsonb, 2, 'elective3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Bringing the Li River Back to Life', 'The Li River in Guangxi is famous for its clear water and beautiful hills, and millions of visitors come to enjoy it every year. Sadly, this fame once brought serious problems. Crowds of tourists frequently threw garbage into the water, and the kitchens on tour boats poured used oil straight into the river. As more hotels and small enterprises opened along the banks, even more waste ended up in the water. Local officials were worried that the pollution was destroying the natural beauty, so they decided to act. A comprehensive plan was carried out. Workers built stations to treat waste water, and the collection of household rubbish was improved. Dozens of polluting factories were closed or moved away. Strict regulations controlled new building, and clear rules were made about where boats could go and how garbage should be handled. Officers also began regular inspections and would fine any company that broke the rules. Thanks to these efforts, the Li River is now heading towards a clean and sustainable future, and its famous scenery has been restored.', '说明·漓江治污', 176, '[{"q":"What was one main cause of the river''s pollution?","answer":"A","options":["Visitors and tour boats dropping waste into the water.","Heavy rain washing in mud.","Fish dying of old age.","Too few people visiting the area."],"explanation":"原文 ''tourists frequently threw garbage… kitchens on tour boats poured used oil'' 的转述。"},{"q":"What did the officials do about the polluting factories?","answer":"B","options":["They gave them more money.","They closed or moved many of them.","They built more of them.","They ignored the problem."],"explanation":"原文 ''Dozens of polluting factories were closed or moved away'' 的转述。"},{"q":"How did officers make sure the new rules were obeyed?","answer":"C","options":["By asking tourists to leave.","By closing the whole river to boats.","By inspecting regularly and fining rule-breakers.","By doing nothing once the plan started."],"explanation":"原文 ''regular inspections and would fine any company that broke the rules'' 的转述。"}]'::jsonb, '[{"word":"enterprise","cn":"企业"},{"word":"regulation","cn":"规章"},{"word":"inspection","cn":"检查"}]'::jsonb, 2, 'elective3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Green Miracle of Saihanba', 'Saihanba lies in the north of China, near the edge of a great desert. Long ago it was a rich green land, but years of cutting trees left it bare and dry. Cold winds carried sand towards the capital, and the soil could no longer hold water. In 1962, a group of young workers were sent to this empty place with one task: to grow a forest where almost nothing would grow. Life there was very hard. The winters were bitter, food was simple, and many of their first trees died. Yet the workers did not give up. They learned from each failure, chose stronger young trees, and planted them year after year. Their children and grandchildren carried on the same work. After about sixty years, the bare hills had become the largest planted forest in the world. Today this huge sea of green cleans the air, holds back the sand, and keeps water in the ground. The story of Saihanba shows that with patience and team effort, people can restore even the most damaged land.', '记叙·塞罕坝绿色奇迹', 176, '[{"q":"Why had Saihanba become bare and dry?","answer":"D","options":["Because it had always been a desert.","Because of heavy rain every winter.","Because no one had ever lived near it.","Because too many trees had been cut down over the years."],"explanation":"原文 ''years of cutting trees left it bare and dry'' 的转述。"},{"q":"How did the workers finally succeed in growing the forest?","answer":"A","options":["They kept learning from failure and planting for many years.","They gave up and tried somewhere else.","They waited for the trees to grow by themselves.","They moved the desert away."],"explanation":"原文 ''learned from each failure… planted them year after year'' 的转述。"},{"q":"What does the writer say the Saihanba story proves?","answer":"B","options":["Forests can grow anywhere with no effort.","Patient teamwork can repair badly damaged land.","Deserts can never be changed at all.","Only machines can plant trees."],"explanation":"末句 ''with patience and team effort, people can restore even the most damaged land'' 的转述。"}]'::jsonb, '[{"word":"restore","cn":"恢复;修复"},{"word":"ecology","cn":"生态"},{"word":"sustain","cn":"维持"}]'::jsonb, 2, 'elective3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Small Habits, Big Difference', 'Protecting the planet does not always mean doing something huge. In fact, many small daily habits can lower your carbon footprint a great deal. Think about energy first. When you leave a room, turn off the light, and unplug the TV and computer instead of leaving them on standby. On a cold day, put on a warm sweater before you turn up the heat, and wash your clothes in cold water when you can. Think about transport too. For short trips, walk or ride a bike rather than asking your parents to drive you. Each ride you skip means less carbon dioxide in the air. Then there is waste. Carry a cloth bag when you go shopping so that you do not need plastic ones. Sort your rubbish so that paper, glass and metal can be recycled. None of these actions is difficult, yet together they save energy, save money, and keep the air cleaner. If everyone in a city formed just a few green habits, the whole world would feel the difference.', '说明·绿色生活习惯', 173, '[{"q":"What is the writer''s main point about protecting the planet?","answer":"C","options":["Only big projects can help the planet.","Nothing ordinary people do really matters.","Many small everyday habits can make a real difference.","Only the government can save energy."],"explanation":"原文 ''many small daily habits can lower your carbon footprint a great deal'' 的转述。"},{"q":"What does the text suggest doing for short trips?","answer":"D","options":["Always ask your parents to drive.","Stay at home and never go out.","Take a taxi to save time.","Travel on foot or by bicycle rather than by car."],"explanation":"原文 ''walk or ride a bike rather than asking your parents to drive you'' 的转述。"},{"q":"According to the writer, what would happen if everyone formed green habits?","answer":"A","options":["People everywhere would notice the improvement.","Energy bills would rise sharply.","Nothing would change at all.","Cities would become dirtier."],"explanation":"末句 ''the whole world would feel the difference'' 的转述。"}]'::jsonb, '[{"word":"footprint","cn":"(碳)足迹"},{"word":"moderate","cn":"适度的"},{"word":"sustainable","cn":"可持续的"}]'::jsonb, 2, 'elective3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Promise of Clean Energy', 'For a long time, the world has run mainly on fossil fuels. Coal, oil and gas power our cars, homes and factories, but burning them fills the air with carbon dioxide and other harmful gases. As a result, the planet is getting warmer and the air in many cities is no longer safe to breathe. This is why so many countries are now turning to clean energy. The sun, the wind and moving water can all be used to make electricity without polluting the air. Sunlight falling on solar panels, for example, can light a school or heat a home. Wind farms on open land turn the power of the breeze into clean electricity. These sources will not run out, and they do not release smog or carbon dioxide. Of course, the change is not simple. Clean energy can cost more at first, and the weather is not always sunny or windy. Yet most experts agree that this is the path we must take. If we are willing to invest today, clean energy can sustain a healthy and habitable world for the children of tomorrow.', '说明·清洁能源', 185, '[{"q":"Why are many countries turning to clean energy?","answer":"B","options":["Because fossil fuels have already run out.","Because burning fossil fuels warms the planet and dirties the air.","Because clean energy is always cheaper.","Because people dislike cars."],"explanation":"原文 ''burning them fills the air with carbon dioxide… planet is getting warmer'' 的转述。"},{"q":"What is one advantage of the sun and the wind as energy sources?","answer":"C","options":["They are easy to store in bottles.","They work better than anything at night.","They never get used up and keep the air clean.","They are owned by only a few people."],"explanation":"原文 ''will not run out, and they do not release smog or carbon dioxide'' 的转述。"},{"q":"What difficulty about clean energy does the writer admit?","answer":"D","options":["It makes the air dirtier.","It cannot make electricity at all.","No country wants to use it.","It is dearer to start with and relies on sunshine or wind."],"explanation":"原文 ''can cost more at first, and the weather is not always sunny or windy'' 的转述。"}]'::jsonb, '[{"word":"release","cn":"排放"},{"word":"habitable","cn":"适合居住的"},{"word":"sustain","cn":"维持"}]'::jsonb, 2, 'elective3', 'U3');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U3', 'My Green Week', 'This week our class started a project to live in a greener (1)____. Each of us promised to do small things to protect the (2)____. On Monday I turned off every (3)____ before leaving the room, and I unplugged the computer instead of leaving it on standby. On Tuesday I carried a cloth bag to the shop so that I did not need a (4)____ one. On Wednesday I rode my (5)____ to school instead of asking my dad to drive me, which gave off less carbon dioxide. On Thursday I learned to (6)____ our rubbish into paper, glass and metal so that it could be reused. On Friday I took a shorter shower to (7)____ water. By the end of the week, I felt (8)____ of these new habits. None of them was (9)____, yet together they really helped to cut my carbon (10)____. I plan to keep them up for the rest of the year.', 157, 2, '[{"q":"1","answer":"A","options":["way","price","noise","machine"],"explanation":"in a greener way 以更环保的方式。"},{"q":"2","answer":"B","options":["market","environment","ticket","garden"],"explanation":"protect the environment 保护环境。"},{"q":"3","answer":"C","options":["song","price","light","noise"],"explanation":"turn off every light 关掉每盏灯。"},{"q":"4","answer":"D","options":["clean","warm","loud","plastic"],"explanation":"a plastic bag 塑料袋,与 cloth bag 相对。"},{"q":"5","answer":"A","options":["bike","boat","plane","train"],"explanation":"rode my bike 骑自行车。"},{"q":"6","answer":"B","options":["sell","sort","lose","throw"],"explanation":"sort rubbish 把垃圾分类。"},{"q":"7","answer":"C","options":["waste","sell","save","lose"],"explanation":"save water 节约用水。"},{"q":"8","answer":"D","options":["afraid","tired","bored","proud"],"explanation":"feel proud of 为……感到自豪。"},{"q":"9","answer":"A","options":["difficult","cheap","empty","loud"],"explanation":"none was difficult 没有一件是困难的。"},{"q":"10","answer":"B","options":["price","footprint","weather","machine"],"explanation":"carbon footprint 碳足迹。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U3', 'A Town That Recycles', 'Greenfield used to be a town with a serious (1)____ problem. Rubbish was left in the streets, and dirty water was poured into the river. The local (2)____ decided that something had to be done. First, they made strict (3)____ about how waste should be handled. Bins of three colours were placed on every street so that people could (4)____ paper, glass and metal. Trucks came to (5)____ the rubbish twice a week and took it to a clean station. Factories that broke the rules had to pay a heavy (6)____. The government also began regular (7)____ to make sure the rules were followed. Slowly the air and water grew much (8)____. Today Greenfield is a clean and (9)____ town, and other places come to learn from it. The mayor often says that everyone, from children to old people, helped to (10)____ the beauty of their home.', 147, 2, '[{"q":"1","answer":"C","options":["music","holiday","pollution","price"],"explanation":"a pollution problem 污染问题。"},{"q":"2","answer":"D","options":["weather","noise","garden","government"],"explanation":"the local government 当地政府。"},{"q":"3","answer":"A","options":["regulations","songs","prices","tickets"],"explanation":"strict regulations 严格的规章。"},{"q":"4","answer":"B","options":["eat","recycle","sell","lose"],"explanation":"recycle 回收利用。"},{"q":"5","answer":"C","options":["sell","buy","collect","hide"],"explanation":"collect the rubbish 收集垃圾。"},{"q":"6","answer":"D","options":["song","gift","meal","fine"],"explanation":"pay a heavy fine 缴纳重罚款。"},{"q":"7","answer":"A","options":["inspections","holidays","parties","games"],"explanation":"regular inspections 定期检查。"},{"q":"8","answer":"B","options":["worse","cleaner","dirtier","louder"],"explanation":"much cleaner 干净得多。"},{"q":"9","answer":"C","options":["noisy","dirty","healthy","empty"],"explanation":"a clean and healthy town 干净健康的小镇。"},{"q":"10","answer":"D","options":["waste","sell","lose","restore"],"explanation":"restore the beauty 恢复美景。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U3', 'Reading the Carbon Graph', 'In science class our teacher showed us a (1)____ about carbon dioxide in the air. The line on it went up year after year, which was a worrying (2)____. She explained that most of this gas comes from burning (3)____ fuels such as coal and oil. When we drive cars or run factories, we (4)____ carbon dioxide into the sky. This gas traps (5)____ around the earth, so the planet slowly gets (6)____. As a result, the ice at the poles begins to (7)____, and the level of the sea rises. The teacher said that this is now a (8)____ problem that affects every country. But she also gave us (9)____. If people use clean energy and cut their carbon (10)____, the line on the graph can start to fall again. We left the class knowing that our daily choices really matter.', 142, 2, '[{"q":"1","answer":"A","options":["graph","song","price","meal"],"explanation":"a graph 图表。"},{"q":"2","answer":"B","options":["price","trend","noise","garden"],"explanation":"a worrying trend 令人担忧的趋势。"},{"q":"3","answer":"C","options":["clean","wet","fossil","loud"],"explanation":"fossil fuels 化石燃料。"},{"q":"4","answer":"D","options":["save","hide","sell","release"],"explanation":"release carbon dioxide 排放二氧化碳。"},{"q":"5","answer":"A","options":["heat","rain","snow","wind"],"explanation":"traps heat 锁住热量。"},{"q":"6","answer":"B","options":["cooler","warmer","smaller","quieter"],"explanation":"gets warmer 变得更暖。"},{"q":"7","answer":"C","options":["sell","grow","melt","stop"],"explanation":"ice begins to melt 冰开始融化。"},{"q":"8","answer":"D","options":["cheap","funny","happy","worldwide"],"explanation":"a worldwide problem 全球性问题。"},{"q":"9","answer":"A","options":["hope","noise","money","rubbish"],"explanation":"gave us hope 给了我们希望。"},{"q":"10","answer":"B","options":["prices","emissions","songs","tickets"],"explanation":"carbon emissions 碳排放。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U3', 'Tree-Planting Day', 'Last Saturday our whole school joined a tree-planting (1)____ on a bare hillside. The land there was dry and (2)____, because too many trees had been cut down in the past. Our teacher told us that young trees would help to hold the (3)____ and keep water in the ground. Each group was given a few small trees to (4)____. At first the work was (5)____, and my hands soon hurt from digging. But nobody wanted to give (6)____. We dug holes, placed the trees in carefully, and gave each one plenty of (7)____. By noon the empty hill was dotted with rows of green. Our teacher said that in many years these trees would grow into a small (8)____ that cleaned the air. She reminded us that protecting (9)____ is the duty of everyone. As we walked home, tired but happy, I felt proud that we had done something to (10)____ the land.', 154, 2, '[{"q":"1","answer":"C","options":["price","song","event","meal"],"explanation":"a tree-planting event 植树活动。"},{"q":"2","answer":"D","options":["wet","loud","rich","bare"],"explanation":"dry and bare 干燥而光秃。"},{"q":"3","answer":"A","options":["soil","price","noise","music"],"explanation":"hold the soil 固定土壤。"},{"q":"4","answer":"B","options":["eat","plant","sell","lose"],"explanation":"plant trees 种树。"},{"q":"5","answer":"C","options":["easy","cheap","hard","quiet"],"explanation":"the work was hard 工作很辛苦。"},{"q":"6","answer":"D","options":["off","in","out","up"],"explanation":"give up 放弃。"},{"q":"7","answer":"A","options":["water","money","smog","rubbish"],"explanation":"give each one water 给每棵浇水。"},{"q":"8","answer":"B","options":["market","forest","shop","city"],"explanation":"a small forest 一片小森林。"},{"q":"9","answer":"C","options":["money","noise","nature","rubbish"],"explanation":"protecting nature 保护自然。"},{"q":"10","answer":"D","options":["waste","sell","lose","restore"],"explanation":"restore the land 修复土地。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U3', 'Saving Water at Home', 'My grandmother grew up in a village where clean water was hard to (1)____, so she taught me never to (2)____ a single drop. At home we follow several simple (3)____ to save water every day. We always turn off the tap while we (4)____ our teeth, instead of letting it run. When we wash vegetables, we keep the used water to (5)____ the plants in the garden. We also take shorter (6)____ rather than long ones, which saves both water and (7)____. My father even fixed the old tap that used to (8)____ slowly all night. Grandmother says that water is too (9)____ to throw away, and that careful use today will help our whole town in the future. Thanks to her, saving water has become a natural (10)____ for our family, and we feel good about doing our part for the environment.', 144, 2, '[{"q":"1","answer":"A","options":["find","sell","throw","hide"],"explanation":"hard to find 难以找到。"},{"q":"2","answer":"B","options":["save","waste","drink","boil"],"explanation":"never waste a drop 不浪费一滴。"},{"q":"3","answer":"C","options":["prices","songs","habits","tickets"],"explanation":"simple habits 简单的习惯。"},{"q":"4","answer":"D","options":["eat","sell","lose","brush"],"explanation":"brush our teeth 刷牙。"},{"q":"5","answer":"A","options":["water","sell","burn","throw"],"explanation":"water the plants 浇灌植物。"},{"q":"6","answer":"B","options":["meals","showers","songs","prices"],"explanation":"take shorter showers 洗更短的澡。"},{"q":"7","answer":"C","options":["noise","rubbish","energy","smog"],"explanation":"saves water and energy 既省水又省能。"},{"q":"8","answer":"D","options":["sing","grow","fly","drip"],"explanation":"the tap used to drip 水龙头滴水。"},{"q":"9","answer":"A","options":["precious","cheap","loud","empty"],"explanation":"too precious to throw away 太宝贵而不能浪费。"},{"q":"10","answer":"B","options":["price","habit","noise","machine"],"explanation":"a natural habit 自然而然的习惯。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U3', 'An Interview about Smog', 'Last week a radio host (1)____ an expert about the smog that sometimes covers big cities. The expert explained that smog is a kind of dirty (2)____ formed when smoke mixes with fog. He said it becomes worse when too many people (3)____ coal and too many cars are on the road. Breathing such air is very (4)____ to health, especially for children and old people. The host asked what cities could (5)____ to solve the problem. The expert answered that they must (6)____ the number of cars on busy days and move polluting factories away. He also advised everyone to use cleaner (7)____ such as solar and wind power. When asked whether the air could really get (8)____, he smiled and said yes. He pointed to London, where strong (9)____ once cleared away a deadly smog. With the right action, he believed, any city could enjoy a clean and (10)____ future.', 152, 2, '[{"q":"1","answer":"C","options":["sold","ate","interviewed","lost"],"explanation":"interviewed an expert 采访专家。"},{"q":"2","answer":"D","options":["song","price","meal","air"],"explanation":"dirty air 污浊的空气。"},{"q":"3","answer":"A","options":["burn","save","wash","buy"],"explanation":"burn coal 烧煤。"},{"q":"4","answer":"B","options":["useful","harmful","kind","polite"],"explanation":"harmful to health 有害健康。"},{"q":"5","answer":"C","options":["eat","sell","do","sing"],"explanation":"what cities could do 城市能做什么。"},{"q":"6","answer":"D","options":["grow","waste","sell","restrict"],"explanation":"restrict the number of cars 限制车辆数量。"},{"q":"7","answer":"A","options":["energy","prices","noises","tickets"],"explanation":"cleaner energy 更清洁的能源。"},{"q":"8","answer":"B","options":["worse","cleaner","dirtier","louder"],"explanation":"get cleaner 变得更干净。"},{"q":"9","answer":"C","options":["songs","noises","laws","meals"],"explanation":"strong laws 强有力的法律。"},{"q":"10","answer":"D","options":["dirty","noisy","empty","healthy"],"explanation":"a clean and healthy future 清洁健康的未来。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U3 听力·对话 Joining the Green Club', '选择性必修三 U3 · dialogue', 3, 'A: Hi, Mark, I heard you joined the school Green Club. What do you do there?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U3 听力·短文 Why the Earth Is Warming', '选择性必修三 U3 · passage', 2, 'Our planet is slowly getting warmer, and this change worries many scientists.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U3 听力·对话 How Do You Get to School?', '选择性必修三 U3 · dialogue', 3, 'A: Anna, how do you usually get to school in the morning?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U3 听力·短文 The Forest That People Made', '选择性必修三 U3 · passage', 2, 'Long ago, Saihanba in northern China was bare and dry land near a desert.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U3 听力·对话 Talking about Smog in Class', '选择性必修三 U3 · dialogue', 3, 'A: Mr Lee, why does our city sometimes have such heavy smog?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U3 听力·短文 Simple Ways to Save Energy', '选择性必修三 U3 · passage', 2, 'Saving energy at home is easier than many people think.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Write a Report on an Environmental Issue(就一个环境问题写一篇报道)', 'A Report on an Environmental Issue', '假设你叫李华,你们学校的英文报正在征集一篇关于环境问题的报道。请用英语写一篇约100词的报道,内容包括:① 清楚说明你身边的一个环境问题(如水污染/空气污染/垃圾)及其原因;② 介绍已经采取的一两项措施;③ 提出你的建议或呼吁。注意:报道客观、条理清楚,可适当使用间接引语转述他人的话。', 'Suppose you are Li Hua. Your school''s English newspaper is collecting reports on environmental issues. Write a report (about 100 words) including: 1) a clear description of one environmental problem near you and its causes (e.g. water pollution, air pollution, rubbish); 2) one or two measures that have already been taken; 3) your own suggestion or call to action.', '["说明问题及原因(One serious problem in our town is … This is mainly caused by …)","已采取的措施(To deal with it, the local government has … New rules require people to …)","提出建议/呼吁(I believe we should … Together we can …)","客观条理、可用间接引语转述(An expert said that …)"]'::jsonb, 70, 100, 'Water pollution is a serious problem in our town. In the past, factories along the river released waste water, and many people frequently threw garbage into it, so the water became dirty and the fish began to disappear. To deal with this, the local government has taken action. Several polluting factories were closed or moved away, and strict rules now control how waste should be handled. Officers also carry out regular inspections and fine those who break the rules. An expert told us that the water was getting cleaner year by year. I believe we should all do our part by saving water and never dropping litter. Together we can restore the beauty of our river.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Water pollution is a serious problem in our town.","Several polluting factories were closed or moved away, and strict rules now control how waste should be handled.","An expert told us that the water was getting cleaner year by year.","Together we can restore the beauty of our river."]'::jsonb, '[{"wrong":"The factory release waste water.","correct":"The factory releases waste water.","note":"主语第三人称单数,动词加 s。"},{"wrong":"Many garbage was thrown into the river.","correct":"A lot of garbage was thrown into the river.","note":"garbage 不可数,不用 many,用 a lot of / much。"},{"wrong":"The expert said the water is getting cleaner.","correct":"The expert said the water was getting cleaner.","note":"间接引语时态后移:is→was。"}]'::jsonb, '【环境报道结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective3', 'U3', '{"title":"直接引语 → 间接引语 速查","intro":"把别人说的话转述出来,就是把直接引语变间接引语。三步走:① 选对引导词;② 时态后移;③ 人称、指示词和时间/地点状语呼应。主句若是一般过去时(said/asked/told),从句时态一般要后移。","table":{"headers":["句类","引导词 / 结构","例(直接 → 间接)"],"rows":[["陈述句","say/tell (sb) + that(可省)","He said, \"I recycle.\" → He said (that) he recycled."],["一般疑问句","ask + if/whether + 陈述语序","She asked, \"Do you save water?\" → She asked if I saved water."],["特殊疑问句","ask + wh-词 + 陈述语序","He asked, \"What can we do?\" → He asked what we could do."],["祈使句","tell/ask/order/advise sb (not) to do","\"Don''t litter,\" he said. → He told us not to litter."]]},"specialRules":[{"rule":"时态后移:do→did, is→was, will→would, can→could, have done→had done","mark":"is recycling → was recycling"},{"rule":"疑问句一律变陈述语序:主语在前、去掉助动词 do/does/did 的倒装","mark":"Do you …? → if I … / Where does it …? → where it …"},{"rule":"指示词与时间/地点状语呼应","mark":"now→then, today→that day, tomorrow→the next day, this→that, here→there"},{"rule":"人称随说话人/听话人变换","mark":"I→he/she, you→I/we, we→they"}],"why":["转述是站在「现在、别处」复述「当时、别处」说的话,所以时间参照点变了——时态要后退一步,指示词和时间/地点词也要相应改变,听话人才不会误会是此时此地的事。"],"gaokaoPoints":["语法填空/短文改错高频:疑问句转述忘记改陈述语序(仍写成 if you do)、时态没后移(said … is)是最常见失分点。","祈使句转述要用动词不定式:tell/ask/order/advise sb (not) to do,否定式 not 放 to 前。"],"examVsReal":[{"exam":"She asked whether I saved water.（考试/书面)","real":"She asked if I save water.","note":"考试严格要求 whether/if + 时态后移;口语里若情况仍为真,时态有时不后移"},{"exam":"He said that he recycled paper.（考试)","real":"He said he recycles paper.","note":"考试 said 后从句后移为 recycled;口语陈述仍然成立的习惯时常保留现在时"}]}'::jsonb);
